if (shareAppBtn) {
  shareAppBtn.addEventListener("click", async () => {
    const title = "Milk Bahi App";
    const text2 = "\u{1F44B} Hi! I use Milk Bahi to track my daily milk expenses. It's simple and works offline. You can download the app file directly from here:";
    const url = "https://github.com/pavnxet/Milk-Bahi/releases";
    try {
      await Share.share({
        title,
        text: text2,
        url,
        dialogTitle: "Share App"
      });
    } catch (error) {
      console.warn("Capacitor Share failed, trying Navigator Share", error);
      if (navigator.share) {
        try {
          await navigator.share({
            title,
            text: text2,
            url
          });
        } catch (err2) {
          console.error("Navigator Share failed", err2);
        }
      } else {
        try {
          await navigator.clipboard.writeText(`${text2} ${url}`);
          alert("Link copied to clipboard!");
        } catch (err2) {
          alert(`Share this link: ${url}`);
        }
      }
    }
  });
}
